/**
 * Concatenates supabase/migrations/*.sql (in order) into supabase/APPLY_ALL.sql,
 * so the whole schema can be pasted into the Supabase SQL Editor in one go.
 * Run: npm run db:bundle
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = join(import.meta.dirname, '..', 'supabase', 'migrations');
const files = readdirSync(dir).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();

const header = `-- =============================================================================
-- APPLY_ALL.sql — GENERATED by \`npm run db:bundle\`. Do not edit by hand;
-- edit the files in supabase/migrations/ and re-run the bundle.
-- Paste this whole file into Supabase Dashboard -> SQL Editor -> Run.
-- Safe to re-run. Contains: ${files.join(', ')}
-- =============================================================================
`;

const body = files.map((f) => `\n-- >>>>>>>>>> ${f}\n${readFileSync(join(dir, f), 'utf8').trim()}\n`).join('');
writeFileSync(join(dir, '..', 'APPLY_ALL.sql'), header + body);
console.log(`Bundled ${files.length} migrations -> supabase/APPLY_ALL.sql`);
